<div class="card"><div class="card-header"><h3 class="card-title">Students Eligible to Return</h3></div><div class="card-body border-bottom py-3"><div class="input-icon"><span class="input-icon-addon"><i class="ti ti-search"></i></span><input id="reentry-search" class="form-control form-control-sm" placeholder="Search student ID or name"></div></div><div class="table-responsive"><table class="table card-table table-vcenter"><thead><tr><th>Student</th><th>Withdrawn Academic Year</th><th>Campus</th><th>Grade/Class</th><th>Withdrawal Date</th></tr></thead><tbody id="reentry-table"><tr><td colspan="5" class="text-center">Loading...</td></tr></tbody></table></div></div>
