@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const field=id=>document.getElementById(id),modal=bootstrap.Modal.getOrCreateInstance(field('reentryModal')),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),fill=(id,items,label,empty)=>{field(id).innerHTML='<option value="">'+empty+'</option>'+(items||[]).map(item=>'<option value="'+item.id+'">'+esc(item[label])+'</option>').join('')},studentLabel=item=>`${item.student?.student_id||item.student?.student_no||''} - ${item.student?.first_name_en||''} ${item.student?.last_name_en||''}`,state={};const render=()=>{const term=field('reentry-search').value.toLowerCase();field('reentry-table').innerHTML=(state.withdrawals||[]).filter(x=>studentLabel(x).toLowerCase().includes(term)).map(x=>'<tr><td>'+esc(studentLabel(x))+'</td><td>'+esc(x.academic_year?.academic_year||'-')+'</td><td>'+esc(x.campus?.campus_name_en||'-')+'</td><td>'+esc((x.grade?.grade||'-')+' '+(x.school_class?.class_name||''))+'</td><td>'+esc(x.effective_on||'-')+'</td></tr>').join('')||'<tr><td colspan="5" class="text-center text-secondary">No students eligible to return.</td></tr>'};const load=async()=>{state=await (await fetch('{{ route('student-reentry.options') }}')).json();fill('reentry-year',state.academicYears,'academic_year','Select Academic Year');fill('reentry-campus',state.campuses,'campus_name_en','Select Campus');fill('reentry-grade',state.grades,'grade','Select Grade');fill('reentry-class',state.classes,'class_name','Select Class');fill('reentry-group',state.groups,'session_short_name','Select Group');field('reentry-source').innerHTML='<option value="">Select withdrawn student</option>'+(state.withdrawals||[]).map(x=>'<option value="'+x.id+'">'+esc(studentLabel(x))+'</option>').join('');render()};field('reentry-search').oninput=render;field('reentry-student-search').oninput=()=>{const term=field('reentry-student-search').value.toLowerCase();Array.from(field('reentry-source').options).forEach((option,index)=>option.hidden=index>0&&!option.textContent.toLowerCase().includes(term))};field('reentry-source').onchange=()=>{const x=(state.withdrawals||[]).find(item=>String(item.id)===field('reentry-source').value);field('reentry-source-info').textContent=x?`Withdrawn: ${x.academic_year?.academic_year||'-'} | ${x.campus?.campus_name_en||'-'} | ${(x.grade?.grade||'-')} ${(x.school_class?.class_name||'')}`:''};field('newReentry').onclick=async()=>{field('reentryForm').reset();field('reentry-date').value=new Date().toISOString().slice(0,10);field('reentry-error').classList.add('d-none');await load();modal.show()};field('reentryForm').onsubmit=async e=>{e.preventDefault();const payload={source_history_id:field('reentry-source').value,academic_year_id:field('reentry-year').value,campus_id:field('reentry-campus').value,grade_id:field('reentry-grade').value,class_id:field('reentry-class').value,session_id:field('reentry-group').value,effective_on:field('reentry-date').value,notes:field('reentry-notes').value};const response=await fetch('{{ route('student-reentry.save') }}',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok){field('reentry-error').textContent=result.message||Object.values(result.errors||{})[0]?.[0]||'Unable to save re-entry.';field('reentry-error').classList.remove('d-none');return}modal.hide();await load()};load()});
</script>@endpush
